"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[95665],{95665:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/just-one-more-lie.png\\"\\n          title=\\"Just One More Lie\\"\\n          author=\\"Keigo Higashino\\"\\n          publisher=\\"Hyundae Munhak\\"\\n          publishedDate=\\"2009-07-27\\"\\n          isbn=\\"9788972754404\\"\\n          rating=3\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\nThis work is a collection of five short stories, each dealing with an independent case, but showing various aspects of human nature manifested through the act of <mark>lying</mark>.  \\n<br>\\nIt is said to be the only short story collection in the ```Detective Kaga``` series.  \\n<br>\\nThe culprits appearing in the work conceal the truth for their own desperate reasons, and build a precarious castle wall by piling another lie on top of it.  \\n<br>\\nDetective Kaga finds minute cracks in this seemingly solid wall of lies and drives in a decisive wedge.  \\nHe engages in high-level psychological warfare, pressuring the culprit to eventually <mark>induce them to tell just one more lie</mark>.  \\n<br>\\nThe human weakness, twisted desires, noble but tragic love, and the weight of guilt revealed in this process are the core fun and themes of this work.  "}')}}]);